=== FILE: apb_gpio.v ===
// apb_gpio: APB4 general-purpose I/O block with interrupt detection.
// Implements interface_spec.md through the plan in microarchitecture.md.
// Zero wait states, synchronous active-low reset, single clock (pclk).
module apb_gpio #(
  parameter integer ADDR_WIDTH = 8,
  parameter integer N          = 8
) (
  input  wire                  pclk,
  input  wire                  presetn,
  input  wire [ADDR_WIDTH-1:0] paddr,
  input  wire                  psel,
  input  wire                  penable,
  input  wire                  pwrite,
  input  wire [31:0]           pwdata,
  input  wire [3:0]            pstrb,
  output reg  [31:0]           prdata,
  output wire                  pready,
  output wire                  pslverr,
  input  wire [N-1:0]          gpio_in,
  output wire [N-1:0]          gpio_out,
  output wire [N-1:0]          gpio_oe,
  output wire                  irq
);

  // Bits 0 to N-1 set: the pins that exist.
  localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

  // Register indices (paddr[5:2]).
  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // ---------------------------------------------------------------
  // APB decode
  // ---------------------------------------------------------------
  wire [3:0] index         = paddr[5:2];
  wire       addr_aligned  = (paddr[1:0] == 2'b00);
  wire       addr_high_ok  = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  wire       addr_index_ok = (index <= IDX_INTR_STATUS);
  wire       mapped        = addr_aligned & addr_high_ok & addr_index_ok;

  wire       access        = psel & penable;          // completing cycle (pready = 1)
  wire       wr_access     = access & pwrite & mapped;
  wire       rd_access     = access & ~pwrite & mapped;

  assign pready  = 1'b1;
  assign pslverr = access & (~mapped | (pwrite & (index == IDX_DATA_IN)));

  // Byte strobes expanded to bits, limited to existing pins.
  wire [31:0] strb_bits = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
  wire [31:0] wmask     = strb_bits & PINS;

  // ---------------------------------------------------------------
  // State
  // ---------------------------------------------------------------
  reg [31:0] data_out_q, dir_q, rise_en_q, fall_en_q, high_en_q, low_en_q, int_en_q;
  reg [31:0] status_q, in_q, in_prev_q;

  reg [31:0] data_out_d, dir_d, rise_en_d, fall_en_d, high_en_d, low_en_d, int_en_d;
  reg [31:0] in_ext;

  // gpio_in widened to 32 bits, zeros above N.
  always @* begin
    in_ext          = 32'd0;
    in_ext[N-1:0]   = gpio_in;
  end

  // Read/write register next state: merge under the write mask.
  always @* begin
    data_out_d = data_out_q;
    dir_d      = dir_q;
    rise_en_d  = rise_en_q;
    fall_en_d  = fall_en_q;
    high_en_d  = high_en_q;
    low_en_d   = low_en_q;
    int_en_d   = int_en_q;
    if (wr_access) begin
      case (index)
        IDX_DATA_OUT:    data_out_d = (data_out_q & ~wmask) | (pwdata & wmask);
        IDX_DIR:         dir_d      = (dir_q      & ~wmask) | (pwdata & wmask);
        IDX_INTR_RISE:   rise_en_d  = (rise_en_q  & ~wmask) | (pwdata & wmask);
        IDX_INTR_FALL:   fall_en_d  = (fall_en_q  & ~wmask) | (pwdata & wmask);
        IDX_INTR_HIGH:   high_en_d  = (high_en_q  & ~wmask) | (pwdata & wmask);
        IDX_INTR_LOW:    low_en_d   = (low_en_q   & ~wmask) | (pwdata & wmask);
        IDX_INTR_ENABLE: int_en_d   = (int_en_q   & ~wmask) | (pwdata & wmask);
        default: begin
        end
      endcase
    end
  end

  // Detection and status: detection beats clear (OR applied last).
  wire [31:0] rise_evt  = in_q & ~in_prev_q;
  wire [31:0] fall_evt  = ~in_q & in_prev_q;
  wire [31:0] detected  = ((rise_evt & rise_en_q) | (fall_evt & fall_en_q) |
                           (in_q & high_en_q) | (~in_q & low_en_q)) & PINS;
  wire [31:0] clear     = (wr_access && (index == IDX_INTR_STATUS)) ? (pwdata & wmask) : 32'd0;
  wire [31:0] status_d  = (status_q & ~clear) | detected;

  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'd0;
      dir_q      <= 32'd0;
      rise_en_q  <= 32'd0;
      fall_en_q  <= 32'd0;
      high_en_q  <= 32'd0;
      low_en_q   <= 32'd0;
      int_en_q   <= 32'd0;
      status_q   <= 32'd0;
      in_q       <= 32'd0;
      in_prev_q  <= 32'd0;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      rise_en_q  <= rise_en_d;
      fall_en_q  <= fall_en_d;
      high_en_q  <= high_en_d;
      low_en_q   <= low_en_d;
      int_en_q   <= int_en_d;
      status_q   <= status_d;
      in_q       <= in_ext;
      in_prev_q  <= in_q;
    end
  end

  // ---------------------------------------------------------------
  // Read data: zero unless a mapped read access
  // ---------------------------------------------------------------
  reg [31:0] rd_mux;
  always @* begin
    case (index)
      IDX_DATA_OUT:    rd_mux = data_out_q;
      IDX_DIR:         rd_mux = dir_q;
      IDX_DATA_IN:     rd_mux = in_q;
      IDX_INTR_RISE:   rd_mux = rise_en_q;
      IDX_INTR_FALL:   rd_mux = fall_en_q;
      IDX_INTR_HIGH:   rd_mux = high_en_q;
      IDX_INTR_LOW:    rd_mux = low_en_q;
      IDX_INTR_ENABLE: rd_mux = int_en_q;
      IDX_INTR_STATUS: rd_mux = status_q;
      default:         rd_mux = 32'd0;
    endcase
    prdata = rd_access ? rd_mux : 32'd0;
  end

  // ---------------------------------------------------------------
  // Pins and interrupt
  // ---------------------------------------------------------------
  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & int_en_q);

`ifdef FORMAL
  // Design-intent assertions (not yet bound to a proof job).
  always @* begin
    assert (pready == 1'b1);
    if (!access) begin
      assert (pslverr == 1'b0);
      assert (prdata == 32'd0);
    end
    assert ((data_out_q & ~PINS) == 32'd0);
    assert ((dir_q      & ~PINS) == 32'd0);
    assert ((int_en_q   & ~PINS) == 32'd0);
    assert ((status_q   & ~PINS) == 32'd0);
    assert ((in_q       & ~PINS) == 32'd0);
  end
`endif

endmodule
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
`timescale 1ns/1ps
// Self-checking testbench for apb_gpio. One APB bus drives four instances
// (N = 1, 8, 13, 32); each 32-bit expectation is masked to the instance's pins.
// Check kinds: 1 prdata, 2 pslverr, 3 pready, 4 irq, 5 gpio_out, 6 gpio_oe.
module apb_gpio_tb;

  localparam [31:0] M1  = 32'h0000_0001;
  localparam [31:0] M8  = 32'h0000_00FF;
  localparam [31:0] M13 = 32'h0000_1FFF;
  localparam [31:0] M32 = 32'hFFFF_FFFF;

  localparam [7:0] A_OUT  = 8'h00;
  localparam [7:0] A_DIR  = 8'h04;
  localparam [7:0] A_IN   = 8'h08;
  localparam [7:0] A_RISE = 8'h0C;
  localparam [7:0] A_FALL = 8'h10;
  localparam [7:0] A_HIGH = 8'h14;
  localparam [7:0] A_LOW  = 8'h18;
  localparam [7:0] A_EN   = 8'h1C;
  localparam [7:0] A_ST   = 8'h20;

  localparam [31:0] RISE_PINS = 32'h0010_0201;  // bits 0, 9, 20
  localparam [31:0] FALL_PINS = 32'h0020_0402;  // bits 1, 10, 21
  localparam [31:0] HIGH_PINS = 32'h0040_0804;  // bits 2, 11, 22
  localparam [31:0] LOW_PINS  = 32'h0080_1008;  // bits 3, 12, 23
  localparam [31:0] IN_PAT    = 32'h5A5A_C33C;

  reg         pclk;
  reg         presetn;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [7:0]  paddr;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [31:0] gin;

  wire [31:0] prdata1, prdata8, prdata13, prdata32;
  wire        pready1, pready8, pready13, pready32;
  wire        pslverr1, pslverr8, pslverr13, pslverr32;
  wire        irq1, irq8, irq13, irq32;
  wire [0:0]  out1, oe1;
  wire [7:0]  out8, oe8;
  wire [12:0] out13, oe13;
  wire [31:0] out32, oe32;

  integer passed;
  integer failed;
  integer step;
  reg [8*64-1:0] nonce;

  apb_gpio #(.ADDR_WIDTH(8), .N(1)) u1 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata1), .pready(pready1),
    .pslverr(pslverr1), .gpio_in(gin[0:0]), .gpio_out(out1), .gpio_oe(oe1), .irq(irq1));

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) u8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8), .pready(pready8),
    .pslverr(pslverr8), .gpio_in(gin[7:0]), .gpio_out(out8), .gpio_oe(oe8), .irq(irq8));

  apb_gpio #(.ADDR_WIDTH(8), .N(13)) u13 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata13), .pready(pready13),
    .pslverr(pslverr13), .gpio_in(gin[12:0]), .gpio_out(out13), .gpio_oe(oe13), .irq(irq13));

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) u32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32), .pready(pready32),
    .pslverr(pslverr32), .gpio_in(gin), .gpio_out(out32), .gpio_oe(oe32), .irq(irq32));

  always #5 pclk = ~pclk;

  // ------------------------------------------------------------------
  // Check primitives
  // ------------------------------------------------------------------
  task chk32(input integer kind, input integer inst, input [31:0] got, input [31:0] want);
    begin
      if (got === want) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("step %0d kind %0d N=%0d: got %h, expected %h", step, kind, inst, got, want);
      end
    end
  endtask

  task chk1(input integer kind, input integer inst, input got, input want);
    begin
      if (got === want) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("step %0d kind %0d N=%0d: got %b, expected %b", step, kind, inst, got, want);
      end
    end
  endtask

  task chk_rd(input [31:0] e);
    begin
      chk32(1, 1,  prdata1,  e & M1);
      chk32(1, 8,  prdata8,  e & M8);
      chk32(1, 13, prdata13, e & M13);
      chk32(1, 32, prdata32, e & M32);
    end
  endtask

  task chk_err(input ee);
    begin
      chk1(2, 1,  pslverr1,  ee);
      chk1(2, 8,  pslverr8,  ee);
      chk1(2, 13, pslverr13, ee);
      chk1(2, 32, pslverr32, ee);
    end
  endtask

  task chk_rdy;
    begin
      chk1(3, 1,  pready1,  1'b1);
      chk1(3, 8,  pready8,  1'b1);
      chk1(3, 13, pready13, 1'b1);
      chk1(3, 32, pready32, 1'b1);
    end
  endtask

  // v = expected (status & enable) over 32 bits
  task chk_irq(input [31:0] v);
    begin
      chk1(4, 1,  irq1,  |(v & M1));
      chk1(4, 8,  irq8,  |(v & M8));
      chk1(4, 13, irq13, |(v & M13));
      chk1(4, 32, irq32, |(v & M32));
    end
  endtask

  task chk_pins(input [31:0] eo, input [31:0] eoe);
    begin
      chk32(5, 1,  {31'd0, out1},  eo & M1);
      chk32(5, 8,  {24'd0, out8},  eo & M8);
      chk32(5, 13, {19'd0, out13}, eo & M13);
      chk32(5, 32, out32,          eo & M32);
      chk32(6, 1,  {31'd0, oe1},   eoe & M1);
      chk32(6, 8,  {24'd0, oe8},   eoe & M8);
      chk32(6, 13, {19'd0, oe13},  eoe & M13);
      chk32(6, 32, oe32,           eoe & M32);
    end
  endtask

  // ------------------------------------------------------------------
  // APB transfers. Each starts with a setup phase at the next falling
  // edge, so consecutive calls are back-to-back transfers.
  // ------------------------------------------------------------------
  task apb_xfer(input wr, input [7:0] a, input [31:0] d, input [3:0] s,
                input [31:0] erd, input eerr, input pin, input [31:0] g);
    begin
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = wr;
      paddr   = a;
      pwdata  = wr ? d : 32'd0;
      pstrb   = wr ? s : 4'd0;
      if (pin) gin = g;
      #1;
      chk_rd(32'd0);
      chk_err(1'b0);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk_rdy;
      chk_err(eerr);
      if (!wr) chk_rd(erd);
      @(posedge pclk);
      #1;
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      pstrb   = 4'd0;
    end
  endtask

  task apb_wr(input [7:0] a, input [31:0] d, input [3:0] s, input ee);
    begin
      apb_xfer(1'b1, a, d, s, 32'd0, ee, 1'b0, 32'd0);
    end
  endtask

  task apb_wr_pin(input [7:0] a, input [31:0] d, input [3:0] s, input ee, input [31:0] g);
    begin
      apb_xfer(1'b1, a, d, s, 32'd0, ee, 1'b1, g);
    end
  endtask

  task apb_rd(input [7:0] a, input [31:0] e, input ee);
    begin
      apb_xfer(1'b0, a, 32'd0, 4'd0, e, ee, 1'b0, 32'd0);
    end
  endtask

  task apb_rd_pin(input [7:0] a, input [31:0] e, input ee, input [31:0] g);
    begin
      apb_xfer(1'b0, a, 32'd0, 4'd0, e, ee, 1'b1, g);
    end
  endtask

  task idle(input integer n);
    integer k;
    begin
      for (k = 0; k < n; k = k + 1) begin
        @(negedge pclk);
        #1;
        chk_rd(32'd0);
        chk_err(1'b0);
      end
    end
  endtask

  task drive_pins(input [31:0] g);
    begin
      @(negedge pclk);
      gin = g;
    end
  endtask

  task rw_pins(input [7:0] a, input [31:0] e);
    begin
      chk_pins((a == A_OUT) ? e : 32'd0, (a == A_DIR) ? e : 32'd0);
      chk_irq(32'd0);
    end
  endtask

  task rw_test(input [7:0] a);
    begin
      apb_wr(a, 32'hFFFF_FFFF, 4'hF, 1'b0); apb_rd(a, 32'hFFFF_FFFF, 1'b0); rw_pins(a, 32'hFFFF_FFFF);
      apb_wr(a, 32'h0000_0000, 4'h5, 1'b0); apb_rd(a, 32'hFF00_FF00, 1'b0); rw_pins(a, 32'hFF00_FF00);
      apb_wr(a, 32'hA5A5_A5A5, 4'hA, 1'b0); apb_rd(a, 32'hA500_A500, 1'b0); rw_pins(a, 32'hA500_A500);
      apb_wr(a, 32'h1234_5678, 4'h0, 1'b0); apb_rd(a, 32'hA500_A500, 1'b0); rw_pins(a, 32'hA500_A500);
      apb_wr(a, 32'h1234_5678, 4'h1, 1'b0); apb_rd(a, 32'hA500_A578, 1'b0); rw_pins(a, 32'hA500_A578);
      apb_wr(a, 32'h0000_0000, 4'hF, 1'b0); apb_rd(a, 32'h0000_0000, 1'b0); rw_pins(a, 32'h0000_0000);
    end
  endtask

  task rd_all_zero_except_in(input [31:0] ein);
    begin
      apb_rd(A_OUT,  32'd0, 1'b0);
      apb_rd(A_DIR,  32'd0, 1'b0);
      apb_rd(A_IN,   ein,   1'b0);
      apb_rd(A_RISE, 32'd0, 1'b0);
      apb_rd(A_FALL, 32'd0, 1'b0);
      apb_rd(A_HIGH, 32'd0, 1'b0);
      apb_rd(A_LOW,  32'd0, 1'b0);
      apb_rd(A_EN,   32'd0, 1'b0);
      apb_rd(A_ST,   32'd0, 1'b0);
    end
  endtask

  // ------------------------------------------------------------------
  // Test sequence
  // ------------------------------------------------------------------
  initial begin
    passed  = 0;
    failed  = 0;
    step    = 0;
    nonce   = {(8*64){1'b0}};
    pclk    = 1'b0;
    presetn = 1'b0;
    psel    = 1'b0;
    penable = 1'b0;
    pwrite  = 1'b0;
    paddr   = 8'd0;
    pwdata  = 32'd0;
    pstrb   = 4'd0;
    gin     = 32'd0;

    // ---- Step 1: reset values ----
    step = 1;
    repeat (2) @(posedge pclk);
    #1;
    chk_pins(32'd0, 32'd0);
    chk_irq(32'd0);
    @(negedge pclk);
    presetn = 1'b1;
    idle(2);
    rd_all_zero_except_in(32'd0);
    chk_pins(32'd0, 32'd0);
    chk_irq(32'd0);

    // ---- Step 2: read/write registers, partial strobes, bits above N ----
    step = 2;  rw_test(A_OUT);
    step = 3;  rw_test(A_DIR);
    step = 4;  rw_test(A_RISE);
    step = 5;  rw_test(A_FALL);
    step = 6;  rw_test(A_HIGH);
    step = 7;  rw_test(A_EN);
    // LOW last: pins are low, so every enabled bit sets status (masked by EN = 0)
    step = 8;  rw_test(A_LOW);
    apb_rd(A_ST, 32'hFFFF_FFFF, 1'b0);
    chk_irq(32'd0);

    // ---- Step 9: write-1-to-clear with strobes ----
    step = 9;
    apb_wr(A_ST, 32'h0000_0001, 4'hF, 1'b0); apb_rd(A_ST, 32'hFFFF_FFFE, 1'b0);
    apb_wr(A_ST, 32'hFFFF_FFFF, 4'h2, 1'b0); apb_rd(A_ST, 32'hFFFF_00FE, 1'b0);
    apb_wr(A_ST, 32'h0000_0000, 4'hF, 1'b0); apb_rd(A_ST, 32'hFFFF_00FE, 1'b0);
    apb_wr(A_ST, 32'hFFFF_0000, 4'h3, 1'b0); apb_rd(A_ST, 32'hFFFF_00FE, 1'b0);
    apb_wr(A_ST, 32'h8000_0000, 4'h8, 1'b0); apb_rd(A_ST, 32'h7FFF_00FE, 1'b0);
    apb_wr(A_ST, 32'hFFFF_FFFF, 4'hF, 1'b0); apb_rd(A_ST, 32'h0000_0000, 1'b0);
    chk_irq(32'd0);

    // ---- Step 10: DATA_IN sampling, read only; PSLVERR policy ----
    step = 10;
    apb_rd_pin(A_IN, IN_PAT, 1'b0, IN_PAT);       // pin set before edge E reads after E
    apb_wr(A_IN, 32'hFFFF_FFFF, 4'hF, 1'b1);      // DATA_IN write: error, no change
    apb_wr(A_IN, 32'h0000_0000, 4'h3, 1'b1);
    apb_rd(A_IN, IN_PAT, 1'b0);
    apb_wr(A_OUT, 32'h0F0F_0F0F, 4'hF, 1'b0);
    chk_pins(32'h0F0F_0F0F, 32'd0);

    step = 11;  // unmapped writes: error, nothing changes (incl. aliases of DATA_OUT)
    apb_wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h28, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'hC0, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h02, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h03, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h41, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h05, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h0D, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_wr(8'h21, 32'hFFFF_FFFF, 4'hF, 1'b1);
    chk_pins(32'h0F0F_0F0F, 32'd0);
    apb_rd(A_OUT,  32'h0F0F_0F0F, 1'b0);
    apb_rd(A_DIR,  32'd0, 1'b0);
    apb_rd(A_IN,   IN_PAT, 1'b0);
    apb_rd(A_RISE, 32'd0, 1'b0);
    apb_rd(A_FALL, 32'd0, 1'b0);
    apb_rd(A_HIGH, 32'd0, 1'b0);
    apb_rd(A_LOW,  32'd0, 1'b0);
    apb_rd(A_EN,   32'd0, 1'b0);
    apb_rd(A_ST,   32'd0, 1'b0);

    step = 12;  // unmapped reads: zero data, error
    apb_rd(8'h24, 32'd0, 1'b1);
    apb_rd(8'h3C, 32'd0, 1'b1);
    apb_rd(8'h40, 32'd0, 1'b1);
    apb_rd(8'h41, 32'd0, 1'b1);
    apb_rd(8'h01, 32'd0, 1'b1);
    apb_rd(8'h81, 32'd0, 1'b1);
    apb_rd(8'hFC, 32'd0, 1'b1);
    apb_rd(8'h0A, 32'd0, 1'b1);
    apb_wr(A_OUT, 32'h0000_0000, 4'hF, 1'b0);
    chk_pins(32'd0, 32'd0);
    drive_pins(32'd0);
    idle(3);

    // ---- Step 13: rising edge, exact timing, fires once ----
    step = 13;
    apb_wr(A_RISE, RISE_PINS, 4'hF, 1'b0);
    apb_wr(A_EN,   RISE_PINS, 4'hF, 1'b0);
    chk_irq(32'd0);
    @(negedge pclk); gin = RISE_PINS;     // before edge E
    @(posedge pclk); #1; chk_irq(32'd0);  // after E: sampled, not yet detected
    @(posedge pclk); #1; chk_irq(RISE_PINS); // after E+1: status set
    apb_rd(A_ST, RISE_PINS, 1'b0);
    apb_rd(A_IN, RISE_PINS, 1'b0);
    apb_wr(A_ST, RISE_PINS, 4'hF, 1'b0);
    apb_rd(A_ST, 32'd0, 1'b0);
    chk_irq(32'd0);
    idle(3);
    apb_rd(A_ST, 32'd0, 1'b0);            // edge does not fire again
    drive_pins(32'd0);
    idle(2);
    apb_rd(A_ST, 32'd0, 1'b0);

    // ---- Step 14: falling edge ----
    step = 14;
    apb_wr(A_FALL, FALL_PINS, 4'hF, 1'b0);
    apb_wr(A_EN,   FALL_PINS, 4'hF, 1'b0);
    drive_pins(FALL_PINS);
    idle(2);
    apb_rd(A_ST, 32'd0, 1'b0);            // rise on these pins not enabled
    @(negedge pclk); gin = 32'd0;
    @(posedge pclk); #1; chk_irq(32'd0);
    @(posedge pclk); #1; chk_irq(FALL_PINS);
    apb_rd(A_ST, FALL_PINS, 1'b0);
    apb_wr(A_ST, FALL_PINS, 4'hF, 1'b0);
    apb_rd(A_ST, 32'd0, 1'b0);
    idle(2);
    apb_rd(A_ST, 32'd0, 1'b0);
    chk_irq(32'd0);

    // ---- Step 15: high level re-sets after a clear ----
    step = 15;
    apb_wr(A_HIGH, HIGH_PINS, 4'hF, 1'b0);
    apb_wr(A_EN,   HIGH_PINS, 4'hF, 1'b0);
    @(negedge pclk); gin = HIGH_PINS;
    @(posedge pclk); #1; chk_irq(32'd0);
    @(posedge pclk); #1; chk_irq(HIGH_PINS);
    apb_rd(A_ST, HIGH_PINS, 1'b0);
    apb_wr(A_ST, HIGH_PINS, 4'hF, 1'b0);
    apb_rd(A_ST, HIGH_PINS, 1'b0);        // level still holds: set again
    chk_irq(HIGH_PINS);
    drive_pins(32'd0);
    idle(2);
    apb_wr(A_ST, HIGH_PINS, 4'hF, 1'b0);
    apb_rd(A_ST, 32'd0, 1'b0);            // level gone: clear sticks
    chk_irq(32'd0);

    // ---- Step 16: low level, enables used as before the edge ----
    step = 16;
    apb_wr(A_EN, LOW_PINS, 4'hF, 1'b0);
    chk_irq(32'd0);
    apb_wr(A_LOW, LOW_PINS, 4'hF, 1'b0);  // commits at edge W
    chk_irq(32'd0);                       // not detected at W
    @(posedge pclk); #1; chk_irq(LOW_PINS); // detected at W+1
    apb_rd(A_ST, LOW_PINS, 1'b0);
    apb_wr(A_ST, LOW_PINS, 4'hF, 1'b0);
    apb_rd(A_ST, LOW_PINS, 1'b0);         // level holds: set again
    drive_pins(LOW_PINS);
    idle(2);
    apb_wr(A_ST, LOW_PINS, 4'hF, 1'b0);
    apb_rd(A_ST, 32'd0, 1'b0);
    chk_irq(32'd0);
    apb_wr(A_LOW, 32'd0, 4'hF, 1'b0);
    drive_pins(32'd0);
    idle(2);
    apb_rd(A_ST, 32'd0, 1'b0);

    // ---- Step 17: clear some pending bits only; interrupt mask ----
    step = 17;
    apb_wr(A_EN, 32'd0, 4'hF, 1'b0);
    drive_pins(RISE_PINS);
    idle(2);
    apb_rd(A_ST, RISE_PINS, 1'b0);        // masked condition still sets status
    chk_irq(32'd0);
    apb_wr(A_ST, 32'h0000_0200, 4'hF, 1'b0); apb_rd(A_ST, 32'h0010_0001, 1'b0);
    apb_wr(A_ST, 32'hFFFF_FFFF, 4'h4, 1'b0); apb_rd(A_ST, 32'h0000_0001, 1'b0);
    apb_wr(A_ST, 32'h0000_0001, 4'hE, 1'b0); apb_rd(A_ST, 32'h0000_0001, 1'b0);
    apb_wr(A_EN, 32'h0000_0002, 4'hF, 1'b0); chk_irq(32'd0);
    apb_wr(A_EN, 32'h0000_0001, 4'hF, 1'b0); chk_irq(32'h0000_0001);
    apb_wr(A_EN, 32'h0000_0000, 4'hF, 1'b0); chk_irq(32'd0);
    apb_rd(A_ST, 32'h0000_0001, 1'b0);
    apb_wr(A_ST, 32'h0000_0001, 4'h1, 1'b0); apb_rd(A_ST, 32'd0, 1'b0);
    drive_pins(32'd0);
    idle(2);
    apb_rd(A_ST, 32'd0, 1'b0);

    // ---- Step 18: a detection beats a clear on the same edge ----
    step = 18;
    apb_wr(A_EN, 32'h0000_0201, 4'hF, 1'b0);
    drive_pins(32'h0000_0201);
    idle(2);
    drive_pins(32'd0);
    idle(2);
    apb_rd(A_ST, 32'h0000_0201, 1'b0);
    chk_irq(32'h0000_0201);
    // pin 0 rises at the setup edge, so its edge is detected on the clear's edge
    apb_wr_pin(A_ST, 32'h0000_0201, 4'hF, 1'b0, 32'h0000_0001);
    apb_rd(A_ST, 32'h0000_0001, 1'b0);
    chk_irq(32'h0000_0001);
    apb_wr(A_ST, 32'h0000_0001, 4'hF, 1'b0);
    apb_rd(A_ST, 32'd0, 1'b0);
    chk_irq(32'd0);
    drive_pins(32'd0);
    idle(2);
    apb_rd(A_ST, 32'd0, 1'b0);

    // ---- Step 19: both edges on one pin; one-cycle pulse ----
    step = 19;
    apb_wr(A_RISE, 32'h0010_0211, 4'hF, 1'b0);
    apb_wr(A_FALL, 32'h0020_0412, 4'hF, 1'b0);
    apb_wr(A_EN,   32'h0000_0010, 4'hF, 1'b0);
    drive_pins(32'h0000_0010);
    idle(2);
    apb_rd(A_ST, 32'h0000_0010, 1'b0);
    chk_irq(32'h0000_0010);
    apb_wr(A_ST, 32'h0000_0010, 4'hF, 1'b0); apb_rd(A_ST, 32'd0, 1'b0);
    drive_pins(32'd0);
    idle(2);
    apb_rd(A_ST, 32'h0000_0010, 1'b0);
    apb_wr(A_ST, 32'h0000_0010, 4'hF, 1'b0); apb_rd(A_ST, 32'd0, 1'b0);
    apb_wr(A_EN, 32'd0, 4'hF, 1'b0);
    @(negedge pclk); gin = 32'h0000_0200;
    @(negedge pclk); gin = 32'd0;
    idle(3);
    apb_rd(A_ST, 32'h0000_0200, 1'b0);
    apb_wr(A_ST, 32'h0000_0200, 4'hF, 1'b0); apb_rd(A_ST, 32'd0, 1'b0);

    // ---- Step 20: reset again with state set ----
    step = 20;
    apb_wr(A_OUT, 32'h1234_5678, 4'hF, 1'b0);
    apb_wr(A_DIR, 32'hFFFF_0000, 4'hF, 1'b0);
    apb_wr(A_EN,  32'hFFFF_FFFF, 4'hF, 1'b0);
    drive_pins(RISE_PINS);
    idle(2);
    apb_rd(A_ST, RISE_PINS, 1'b0);
    chk_pins(32'h1234_5678, 32'hFFFF_0000);
    chk_irq(RISE_PINS);
    @(negedge pclk);
    presetn = 1'b0;
    gin     = 32'd0;
    @(posedge pclk); #1;
    chk_pins(32'd0, 32'd0);
    chk_irq(32'd0);
    repeat (2) @(posedge pclk);
    @(negedge pclk);
    presetn = 1'b1;
    idle(2);
    rd_all_zero_except_in(32'd0);
    chk_pins(32'd0, 32'd0);
    chk_irq(32'd0);
    apb_wr(A_OUT, 32'h0000_00A5, 4'h1, 1'b0);
    apb_rd(A_OUT, 32'h0000_00A5, 1'b0);
    chk_pins(32'h0000_00A5, 32'd0);

    // ---- Verdict ----
    @(negedge pclk);
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
